pub fn pop_last(&mut self) -> Option<(K, V)> {
        self.nodes
            .last()
            .map(|n| unsafe { &*(&n.key as *const _) })
            .map(|key| {
                self.contains_key(key);
                self.non_empty_pop_root()
            })
    }

